  ('83d879dd-926a-57c6-bc6c-12f85992071f', null, (select id from public.skills where slug = 'read-g5-literary-structure-pov'), null, 'hard',
   $q$How would the story most likely be different if Aiko were the narrator?$q$, $q$[{"text":"Readers would never learn that the family owns a cat.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Readers would know about the move at once, and the cat's funny confusion would be lost.","is_correct":true},{"text":"The family would not move, because Aiko would not want to.","is_correct":false,"misconception_token":"confuses-pov-with-plot"},{"text":"The story would describe the move exactly the same way.","is_correct":false,"misconception_token":"ignores-pov-effect"}]$q$::jsonb, $q$Readers would know about the move at once, and the cat's funny confusion would be lost.$q$, $q$Aiko knows the family is moving, so Aiko would explain it right away, and readers would lose the humor of a cat calling it "a city of boxes." Changing the narrator changes how events are described, not what happens, so the move would still take place.$q$, 'draft', '2aec90ce-8690-57bb-9f35-95af48f2911e')
